from math import comb

def calculate_wins(n, p):
    if n == 1:
        return 0 if p == 1 else 1 - comb((p + 1) * (p + 2) // 2, p)
    else:
        m1 = 0
        m2 = 0
        for i in range(n, 1, -1):
            m1 = (m1 + m2) % 1000000007
            m2 = (m1 + (i - n) * m2) % 1000000007
        return (comb(p + 1, n + 1) - m2 - 1) % 1000000007

