from typing import List

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def minimum_insertions(N: int, A: List[int]) -> List[int]:
    visited = [False] * (N + 1)
    dp = [0] * N
    for i in range(N):
        for j in range(i):
            if visited[j]:
                continue
            for k in range(A[j] + 1, A[i] + 1):
                if gcd(A[j], k) == 1 and gcd(k, A[i]) != 1:
                    visited[k] = True
                    dp[j+1] += 1 + dp[k]
                    break
    ans = []
    for i in range(N - 1):
        if not visited[i]:
            ans.append(dp[i])
    return ans

