from collections import defaultdict
from math import gcd

def find_ultimate_weirdness(n, elements, left, right):
    # Construct the common ancestor graph for each element
    tree = defaultdict(list)
    for l in range(left, right + 1):
        for j in range(l - 1, l + 2):
            tree[elements[l]].append(elements[j])

    # Create a sorted list of critical points where we need to check
    sorted_critical_points = sorted([sorted(list(tree[elements[i]]))[-2] for i in range(left, right + 1)])

    if n == 1:
        return 0
    weirdness = [0] * n
    index = [i for i in range(n)]
    with_gcd = True
    while with_gcd:
        with_gcd = False
        tmp_index = []
        for i in range(n - 1):
            if src := tree[index[i + 1]]:
                if gcd(elements[index[i]], elements[i]) == 0:
                    # The gcd of 0 with anything is 0.
                    weirdness[index[i]] = 0
                    n -= 1
                    with_gcd = True
                else:
                    if not src or gcd(elements[index[i]], elements[0]) == gcd(src[0], elements[0]):
                        tmp_index.append(i)
        index = [i for i in index if i not in tmp_index]

    # No further elements remain
    if len(index) == 1:
        return 0
    answer = sorted_critical_points[len(sorted_critical_points) // 2 - 1]
    for i in range(len(index), 0, -1):
        if elements[i] < answer:
            i -= 1
            break
        elif elements[i] > answer:
            i += 1
    return gcd(elements[index[i]], answer)
