def max_beautiful_cuts(bead_counts):
    def dp(ind, pre, is_left):
        if ind == len(bead_counts):
            return 0
        if (ind, pre, is_left) in cache:
            return cache[(ind, pre, is_left)]
        max_cuts = 0
        for color in range(1, 26):
            prev_color = color - 1
            if is_left:
                prev_color = max(0, prev_color - bead_counts[color])
            if bead_counts[color] > prev_color:
                continue
            temp_max_cuts = dp(ind + 1, color, not is_left) + 1
            if ind - 1 >= 0:
                # Check if the cut is beautiful
                palindrome = True
                for i in range(ind - 2, ind + 1):
                    if bead_counts[i] > bead_counts[i + 1]:
                        palindrome = False
                        break
                temp_max_cuts = max(temp_max_cuts, dp(ind - 1, bead_counts[color], not is_left) + palindrome)
            cache[(ind, prev_color, is_left)] = max_cuts = max(max_cuts, temp_max_cuts)
        return cache[(ind, pre, is_left)] if ind > 0 else max_cuts

    cache = {}
    return dp(0, 0, True)

