from bisect import bisect_left, bisect_right

def inedible_tails(L, R):
    if L == 1:
        return 0
    A = sorted([a + G for a in range(ascending(L))])
    mem = [0] * 20 # make every number has idx
    tail = []
    for inv in range(bisect_left(A, 1), ascending(R)):
        mem[A[inv]] += 1 # count number's idx
        if not (inv - 1 < (A[-1] - A[inv])):
            tail.append(A[inv])
    return len(tail)

def ascending(N):
    "Returns the idx of the number N in the ascending number sequence"
    return math.floor(math.log10(N)) + 1 if N > 1 else 1

