def count_ways(n, p):
    from mod import factorial_mod

    mod = 1000000007

    def choose(n, k):
        return factorial_mod(n, mod) // (factorial_mod(k, mod) * factorial_mod(n - k, mod) % mod)

    @lru_cache(maxsize=None)
    def dp(i, prev, rem, minus, plus):
        if i == n:
            return 0 if minus == 0 else 1
        plus_count = rem if prev == 0 else 0
        minus_count = rem - plus_count if prev == 1 else plus_count

        answer = 0
        if minus>0:
            dividers_num = 0
            if minus - 2 <= plus - 1 <= rem:
                dividers_num += plus_count
            if minus == 0:
                if plus < rem:
                    dividers_num += plus_count

            answer = choose(plus_count, minus_num) * divisor(plus, plus_count, rem)
            return answer

        plus_answer = dp(i+1, plus_count, rem, minus, plus_count+1)
        minus_answer = dp(i+1, minus_count, rem, minus, minus_count+1)

    return dp(0, 0, p, 0, 0)


def divisor(p, plus, rem):
    answer = 0
    if rem >= p and rem - 2 >= rem:
        answer += rem % 2

    return answer

