def make_necklace(bead_counts: List[int]) -> str:
    total_beads = sum(bead_counts)
    available_beads = 5
    result = []

    # Simulate the necklace
    for color in range(1, 27):
        for _ in range(bead_counts[color-1]):
            if available_beads == 26:
                break
            result.append(str(color))
            available_beads += 1

    # Ensure the necklace is cyclic
    if available_beads == 26:
        result.append("a")  # Append 'a' to keep ending cyclic

    return "".join(result)

def count_beautiful_cuts(necklace: str):
    if len(necklace) == 0:
        return 0

    # Check for perfect palindromes that end with each character
    perfect_palindromes = []
    for color in range(1, 27):
        if necklace.startswith(str(color) * 2):
            perfect_palindromes.append((color, int(necklace[0] == str(color)) + 1))

    # Count all palindromes as beautiful cuts
    all_palindromes = [0] * len(necklace)
    for i in range(len(necklace)):
        for start, length in perfect_palindromes:
            if necklace.startswith(str(start) * length, i):
                all_palindromes[i] += 1
                break

    return max(necklace.count(color) for color in range(1, 27)) + sum(all_palindromes)

