    if b == 0:
        return a
    return gcd(b, a % b)

def find_good_array_approach(arr, N):
    """Find the minimum number of operations required to convert the array into a good array."""
    n = len(arr)
    if n <= N:
        return -1

    good_operations = 0
    for ops in range(n // N):
        current_operations = 0
        for i in range(n):
            left_gcd = arr[i]
            for j in range(i, n):
                right_gcd = arr[j]
                if gcd(left_gcd, right_gcd) != 1:
                    if i == j:
                        arr = [arr[p].reverse() for p in range(i, n)]
                        good_operations += 1
                    else:
                        reverse_subarray(arr, i, j + 1)
                        good_operations += 1
                    break
                else:
                    current_operations += 1
                    if current_operations == N:
                        return ops + 1, i, j + 1
    return -1

