            positions_missing = set(current_positions[:])
            positions_missing.remove(i)
            string_missing = set(string)
            string_missing.discard(string[i])
            missing_count = tuple([len(positions_missing & word) for word in string_missing])
            c = Counter(missing_count)
            for k, v in c.items():
                first_missing = c.most_common()[0][0]
                joins_str = strings[list(missing_count).index(k)].replace('*', f'${v}').replace('$', f'{k}')
                temp = ''.join([f'0*{k}/*{i}' for i in range(v)])
                join_c = Counter(joins_str + temp)
                for k, v in c.items():
                    if join_c[k] == v:
                        if missing_count not in first_missing:
                            initial_positions.add(i)
                            break
                else:
                    return inf

    choice_prob = factor_in_words_empirical_prob(choose)
