def is_good(arr, n):
    for i in range(n):
        for j in range(i + 1, n):
            subarray_gcd = arr[i]
            for k in range(i, j + 1):
                subarray_gcd = math.gcd(subarray_gcd, arr[k])
            if subarray_gcd != 1:
                return False
    return True

def convert_to_good(arr, n):
    if is_good(arr, n):
        return 0, -1

    min_operations = float('inf')
    optimal_subarray_indices = -1

    for i in range(n - 1):
        for j in range(i + 1, n):
            if is_good(arr, j - i + 1):
                if j - i + 1 < min_operations:
                    min_operations = j - i + 1
                    optimal_subarray_indices = (i, j)

    if min_operations == float('inf'):
        return -1, -1

    rev_start_index = optimal_subarray_indices[0]
    rev_end_index = optimal_subarray_indices[1]
    operations = min_operations

    # Reverse the subarray starting from rev_start_index to rev_end_index
    start = rev_start_index - 1
    end = n + rev_end_index - 1
    array = arr[:]

    while start < end:
        array[start], array[end] = array[end], array[start]
        start += 1
        end -= 1

    return operations, (rev_start_index, start + 1)

def solve(T, inputs):
    for _ in range(T):
        N = inputs[0]
        arr = list(map(int, inputs[1:]))
        ans = convert_to_good(arr, N)
        print(ans)

