def add_range(start, end, val, tree, tree_size):
    while start < tree_size:
        tree[start] += val
        start += start & -start

def update_value(start, end, val, tree, tree_size, node):
    tree[node] = max(tree[node], val)
    if start == end:
        return
    mid = (start + end) // 2
    if start < mid:
        update_value(start, mid, val, tree, tree_size, 2 * node + 1)
    if mid < end:
        update_value(mid + 1, end, val, tree, tree_size, 2 * node + 2)

