from collections import defaultdict

def get_gcd(pairs):
    prime_factors = defaultdict(int)
    for a, b in pairs:
        for prime, power in factors[b]:
            prime_factors[prime] += power / min(a, b)
    return product([(prime, power) for prime, power in prime_factors.items()])

class Solution:
    def ultimateWeght(self, a):
        coalesce = []
        factors = defaultdict(int)
        for i, x in enumerate(a):
            if i == 0 or x != a[i - 1]:
                coalesce.extend((x, i))
                factors[tuple(coalesce)] = i
            coalesce.append((x, len(a) - 1 - i))
            factors[tuple(coalesce[-1])] = i
        pairs = [(a, x, i) for i, (a, x) in enumerate(coalesce)]
        pairs.sort(reverse=True)
        return get_gcd([b - a for a, b in pairs]) / len(a)
