def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def unusual(n, array):
    gcd_array = [0] * n
    for i in range(n - 1):
        for j in range(i + 1, n):
            gcd_array[i] = max(gcd_array[i], gcd(array[i], array[j]))
    return sum(gcd_array)

